import{s as n}from"../supabase-CGTu0p87.js";/* empty css               */import"https://esm.sh/@supabase/supabase-js@2";const u=document.getElementById("admin-login-form"),t=document.getElementById("error-msg"),d=document.getElementById("success-msg"),l=document.getElementById("submit-btn"),y=document.getElementById("setup-link");u.addEventListener("submit",async m=>{m.preventDefault(),t.style.display="none",d.style.display="none",l.disabled=!0,l.textContent="ログイン中...";const a=document.getElementById("email").value,s=document.getElementById("password").value;try{const{data:e,error:i}=await n.auth.signInWithPassword({email:a,password:s});if(i)throw i;const{data:o,error:r}=await n.from("profiles").select("is_admin").eq("id",e.user.id).maybeSingle();if(r)throw r;if(!o||!o.is_admin)throw await n.auth.signOut(),new Error("管理者権限がありません。");window.location.href="index.html"}catch(e){t.textContent=e.message==="Invalid login credentials"?"メールアドレスまたはパスワードが正しくありません。":e.message,t.style.display="block",l.disabled=!1,l.textContent="ログイン"}});y.addEventListener("click",async m=>{m.preventDefault(),t.style.display="none",d.style.display="none";const a=document.getElementById("email").value,s=document.getElementById("password").value;if(!a||!s){t.textContent="メールアドレスとパスワードを入力してからセットアップを押してください。",t.style.display="block";return}if(s.length<6){t.textContent="パスワードは6文字以上にしてください。",t.style.display="block";return}try{const{data:e}=await n.from("profiles").select("id").eq("is_admin",!0).limit(1);if(e&&e.length>0){t.textContent="管理者アカウントは既にセットアップ済みです。ログインしてください。",t.style.display="block";return}const{data:i,error:o}=await n.auth.signUp({email:a,password:s,options:{data:{full_name:"Admin"}}});if(o)throw o;if(i.user){const{data:r,error:c}=await n.rpc("promote_to_admin");if(c)throw c;if(!r)throw new Error("管理者の昇格に失敗しました。")}d.textContent="管理者アカウントを作成しました。上記の情報でログインしてください。",d.style.display="block"}catch(e){t.textContent=`セットアップに失敗しました: ${e.message}`,t.style.display="block"}});
